-- ==============================================================================
-- 2. FUNÇÃO AUXILIAR DE TIMESTAMP (reaproveitada do padrão trazido pelo usuário)
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.atualizado_em = timezone('utc'::text, now());
  RETURN NEW;
END;
$$ LANGUAGE plpgsql

-- ==============================================================================
-- 12. ROW LEVEL SECURITY — habilitado em tudo, sem policies (nega anon/authenticated;
--     service-role sempre ignora RLS, então as server functions continuam funcionando).
-- ==============================================================================
DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
END $$

DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT unnest(ARRAY[
    'projetos', 'projeto_equipe', 'metas', 'entregas', 'atividades',
    'plano_riscos', 'mudancas', 'orcamento_itens', 'orcamento_contrapartidas',
    'evidencias', 'aportes', 'contatos', 'logs_comunicacao',
    'log_alteracoes_meta', 'aprovacoes_pendentes'
  ]) LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS broadcast_change ON public.%I', t);
    EXECUTE format(
      'CREATE TRIGGER broadcast_change AFTER INSERT OR UPDATE OR DELETE ON public.%I ' ||
      'FOR EACH ROW EXECUTE FUNCTION public.broadcast_projetos_change()', t
    );
  END LOOP;
END $$

-- ==============================================================================
-- 10. REALTIME — registra as tabelas novas no canal "projetos-sync" (0002).
-- A renomeação entregas->etapas preserva o trigger existente, mas o nome da
-- tabela no payload muda: quem escuta deve tratar 'etapas'.
-- ==============================================================================
DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT unnest(ARRAY[
    'etapas', 'tarefas', 'pareceres_tecnicos', 'parecer_acoes', 'projeto_anexos'
  ]) LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS broadcast_change ON public.%I', t);
    EXECUTE format(
      'CREATE TRIGGER broadcast_change AFTER INSERT OR UPDATE OR DELETE ON public.%I ' ||
      'FOR EACH ROW EXECUTE FUNCTION public.broadcast_projetos_change()', t
    );
  END LOOP;
END $$

-- ------------------------------------------------------------------------------
-- 5. REALTIME — as tabelas novas entram no canal "projetos-sync" (0002).
-- ------------------------------------------------------------------------------
DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT unnest(ARRAY['orcamento_importacoes', 'orcamento_item_historico']) LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS broadcast_change ON public.%I', t);
    EXECUTE format(
      'CREATE TRIGGER broadcast_change AFTER INSERT OR UPDATE OR DELETE ON public.%I ' ||
      'FOR EACH ROW EXECUTE FUNCTION public.broadcast_projetos_change()', t
    );
  END LOOP;
END $$

DO $$
DECLARE
  principal UUID;
  duplicata UUID;
BEGIN
  SELECT id INTO principal FROM public.comunidades
   WHERE nome = 'Cooperativa dos Agricultores e Apicultores no Nordeste Paraense (CAANP AGROMEL)';
  SELECT id INTO duplicata FROM public.comunidades WHERE nome = 'CAANP-AGROMEL (2ª rota)';
  IF principal IS NOT NULL AND duplicata IS NOT NULL THEN
    UPDATE public.diagnosticos       SET comunidade_id = principal WHERE comunidade_id = duplicata;
    UPDATE public.eventos_calendario SET comunidade_id = principal WHERE comunidade_id = duplicata;
    UPDATE public.projetos           SET comunidade_id = principal WHERE comunidade_id = duplicata;
    UPDATE public.comunidade_pessoas SET comunidade_id = principal WHERE comunidade_id = duplicata;
    DELETE FROM public.comunidades WHERE id = duplicata;
  END IF;
END $$

