)

CREATE OR REPLACE FUNCTION public.orcamento_notas_recalcular()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') AND OLD.item_id IS NOT NULL THEN
    PERFORM public.recalcular_execucao_item(OLD.item_id);
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.item_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.item_id IS DISTINCT FROM OLD.item_id OR NEW.valor <> OLD.valor
          OR NEW.data_emissao <> OLD.data_emissao) THEN
    PERFORM public.recalcular_execucao_item(NEW.item_id);
  END IF;
  RETURN NULL;
END $$

-- Troca a chave primária de comunidade_id para id (só se ainda não trocou).
DO $$
DECLARE pk text;
BEGIN
  SELECT c.conname INTO pk
    FROM pg_constraint c
    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
   WHERE c.conrelid = 'public.organizacao_notas'::regclass
     AND c.contype = 'p'
     AND a.attname = 'comunidade_id';
  IF pk IS NOT NULL THEN
    EXECUTE format('ALTER TABLE public.organizacao_notas DROP CONSTRAINT %I', pk);
    ALTER TABLE public.organizacao_notas ADD PRIMARY KEY (id);
  END IF;
END $$

-- Não exclui, associa ou corrige registros legados automaticamente.
-- A 0018 deve estar aplicada: garante exclusividade inclusive entre criações
-- simultâneas. A guarda abaixo exige vínculo em novos projetos e o congela.
CREATE OR REPLACE FUNCTION public.proteger_vinculo_projeto()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.comunidade_id IS NULL THEN
      RAISE EXCEPTION 'Projeto novo exige vínculo com uma organização.' USING ERRCODE = '23514';
    END IF;
  ELSIF NEW.comunidade_id IS DISTINCT FROM OLD.comunidade_id THEN
    RAISE EXCEPTION 'O vínculo com a organização não pode ser alterado após a criação. Projeto: %', OLD.id
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$

CREATE OR REPLACE FUNCTION public.validar_meta_orcamento() RETURNS trigger
LANGUAGE plpgsql SET search_path = public AS $$
BEGIN
  IF NEW.importacao_id IS NOT NULL AND NEW.meta_id IS NULL THEN
    RAISE EXCEPTION 'Todo item importado deve estar vinculado a uma meta.' USING ERRCODE = '23514';
  END IF;
  IF NEW.meta_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.metas m WHERE m.id = NEW.meta_id AND m.projeto_id = NEW.projeto_id
  ) THEN
    RAISE EXCEPTION 'A meta do orçamento deve pertencer ao mesmo projeto.' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$

-- Ordem manual de irmãos. A transação altera somente ordem e registra o histórico.
CREATE OR REPLACE FUNCTION public.reordenar_plano(
  p_nivel text, p_pai text, p_antes jsonb, p_ids uuid[], p_autor text, p_papel text
) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $$
DECLARE
  tabela text;
  coluna text;
  tipo_pai text;
  filtro text := '';
  projeto bigint;
  entidade public.entidade_operacao_enum;
  atual jsonb;
  esperado jsonb;
  atuais uuid[];
  novos uuid[];
BEGIN
  IF p_nivel = 'meta' THEN
    SELECT id INTO projeto FROM public.projetos WHERE id = p_pai::bigint FOR UPDATE;
    tabela := 'metas'; coluna := 'projeto_id'; tipo_pai := 'bigint'; entidade := 'meta';
  ELSIF p_nivel = 'etapa' THEN
    SELECT projeto_id INTO projeto FROM public.metas WHERE id = p_pai::uuid FOR UPDATE;
    tabela := 'etapas'; coluna := 'meta_id'; tipo_pai := 'uuid'; entidade := 'etapa';
  ELSIF p_nivel = 'atividade' THEN
    SELECT m.projeto_id INTO projeto FROM public.etapas e JOIN public.metas m ON m.id = e.meta_id
      WHERE e.id = p_pai::uuid FOR UPDATE OF e;
    tabela := 'atividades'; coluna := 'etapa_id'; tipo_pai := 'uuid'; entidade := 'especificacao';
    filtro := ' AND excluido_em IS NULL';
  ELSE
    RAISE EXCEPTION 'Nível do plano inválido.';
  END IF;
  IF projeto IS NULL THEN RAISE EXCEPTION 'Origem do plano não encontrada.'; END IF;
  IF p_antes IS NULL OR jsonb_typeof(p_antes) <> 'array' OR p_ids IS NULL OR cardinality(p_ids) = 0 THEN
    RAISE EXCEPTION 'Informe a lista completa de itens.';
  END IF;
  -- Também protege contra edição/exclusão dos irmãos durante esta transação.
  EXECUTE format('SELECT id FROM public.%I WHERE %I = $1::%s%s ORDER BY id FOR UPDATE', tabela, coluna, tipo_pai, filtro) USING p_pai;
  EXECUTE format('SELECT coalesce(jsonb_agg(jsonb_build_object(''id'', id, ''order'', ordem) ORDER BY id), ''[]''::jsonb), array_agg(id ORDER BY id) FROM public.%I WHERE %I = $1::%s%s', tabela, coluna, tipo_pai, filtro)
    INTO atual, atuais USING p_pai;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'order', r."order") ORDER BY r.id), '[]'::jsonb)
    INTO esperado FROM jsonb_to_recordset(p_antes) AS r(id uuid, "order" numeric);
  IF atual IS DISTINCT FROM esperado THEN
    RAISE EXCEPTION 'A lista foi alterada por outra pessoa. Atualize o plano e tente novamente.';
  END IF;
  SELECT array_agg(id ORDER BY id) INTO novos FROM unnest(p_ids) AS t(id);
  IF atuais IS DISTINCT FROM novos OR EXISTS (SELECT 1 FROM unnest(p_ids) AS t(id) GROUP BY id HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'A reordenação deve manter todos os itens da mesma origem, sem duplicações.';
  END IF;
  EXECUTE format('UPDATE public.%I AS item SET ordem = nova.posicao FROM unnest($1::uuid[]) WITH ORDINALITY AS nova(id, posicao) WHERE item.id = nova.id AND item.%I = $2::%s%s', tabela, coluna, tipo_pai, filtro)
    USING p_ids, p_pai;
  INSERT INTO public.log_alteracoes_meta (projeto_id, entidade, acao, parent_id, target_path, campo, de_valor, para_valor, payload, autor, autor_papel, aprovado_por)
    VALUES (projeto, entidade, 'editar', CASE WHEN p_nivel = 'meta' THEN NULL ELSE p_pai::uuid END,
      'Ordenação de ' || tabela, 'ordem', atual::text, to_jsonb(p_ids)::text,
      jsonb_build_object('antes', atual, 'ids', p_ids), p_autor, p_papel, p_autor);
END;
$$

CREATE OR REPLACE FUNCTION public.salvar_versao_orcamento(
  p_projeto bigint, p_antes jsonb, p_itens jsonb, p_autor text, p_importacao jsonb DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE
  atual jsonb; linha jsonb; anterior public.orcamento_itens%ROWTYPE;
  item_id uuid; v_importacao_id uuid; versao integer := 0;
  incluidos integer := 0; alterados integer := 0; arquivados integer := 0;
  ids uuid[] := ARRAY[]::uuid[]; posicao integer := 0;
  nova_meta uuid; quantidade_metas integer; metas_criadas uuid[] := ARRAY[]::uuid[];
BEGIN
  PERFORM 1 FROM public.projetos WHERE id = p_projeto FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Projeto não encontrado.'; END IF;
  PERFORM 1 FROM public.orcamento_itens WHERE projeto_id = p_projeto ORDER BY id FOR UPDATE;
  SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.id), '[]'::jsonb) INTO atual
    FROM public.orcamento_itens o WHERE projeto_id = p_projeto AND vigente;
  IF atual IS DISTINCT FROM p_antes THEN
    RAISE EXCEPTION 'O orçamento foi alterado por outra pessoa. Reabra a prévia e tente novamente.';
  END IF;
  IF jsonb_typeof(p_itens) IS DISTINCT FROM 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'Informe pelo menos um item de orçamento.';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_itens) x GROUP BY x->>'chave_origem' HAVING count(*) > 1) THEN
    RAISE EXCEPTION 'Há itens repetidos. Corrija a correspondência antes de salvar.';
  END IF;
  IF p_importacao IS NOT NULL THEN
    SELECT coalesce(max(o.versao), 0) + 1 INTO versao FROM public.orcamento_importacoes o WHERE projeto_id = p_projeto;
    INSERT INTO public.orcamento_importacoes(projeto_id, nome_arquivo, aba, versao, autor, resumo)
      VALUES(p_projeto, p_importacao->>'nome_arquivo', p_importacao->>'aba', versao, p_autor, p_importacao->'resumo')
      RETURNING id INTO v_importacao_id;
  END IF;
  FOR linha IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    posicao := posicao + 1;
    IF nullif(trim(linha->>'meta_nova'), '') IS NOT NULL THEN
      SELECT count(*), (array_agg(id))[1] INTO quantidade_metas, nova_meta FROM public.metas
        WHERE projeto_id = p_projeto AND nome = linha->>'meta_nova';
      IF quantidade_metas > 1 THEN RAISE EXCEPTION 'Mais de uma meta corresponde ao nome informado.'; END IF;
      IF quantidade_metas = 0 THEN
        INSERT INTO public.metas(projeto_id, nome, ordem)
          SELECT p_projeto, linha->>'meta_nova', coalesce(max(ordem), 0) + 1 FROM public.metas WHERE projeto_id = p_projeto
          RETURNING id INTO nova_meta;
        metas_criadas := array_append(metas_criadas, nova_meta);
      END IF;
      linha := (linha - 'meta_nova') || jsonb_build_object('meta_id', nova_meta);
    END IF;
    IF (linha->>'meta_id' IS NOT NULL OR linha->>'id' IS NULL) AND NOT EXISTS (SELECT 1 FROM public.metas WHERE id = (linha->>'meta_id')::uuid AND projeto_id = p_projeto) THEN
      RAISE EXCEPTION 'A meta não pertence ao projeto.';
    END IF;
    IF coalesce(trim(linha->>'item'), '') = '' OR
      (linha->>'qtd')::numeric < 0 OR (linha->>'qtd_unidades')::numeric < 0 OR
      (linha->>'valor_unitario')::numeric < 0 OR (linha->>'valor_proposto')::numeric < 0 THEN
      RAISE EXCEPTION 'Os dados planejados do item são inválidos.';
    END IF;
    item_id := (linha->>'id')::uuid;
    IF item_id IS NOT NULL THEN
      IF item_id = ANY(ids) THEN RAISE EXCEPTION 'Item repetido na revisão.'; END IF;
      SELECT * INTO anterior FROM public.orcamento_itens WHERE id = item_id AND projeto_id = p_projeto AND vigente;
      IF NOT FOUND THEN RAISE EXCEPTION 'Item não pertence ao orçamento vigente deste projeto.'; END IF;
      IF EXISTS (SELECT 1 FROM jsonb_each(linha - 'id') e WHERE to_jsonb(anterior)->e.key IS DISTINCT FROM e.value) THEN
        alterados := alterados + 1;
        INSERT INTO public.orcamento_item_historico(item_id, evento, autor, valor_anterior, valor_novo, detalhe)
          VALUES(item_id, 'correção de origem', p_autor, anterior.valor_proposto::text,
            linha->>'valor_proposto', jsonb_build_object('origem', coalesce(p_importacao->>'nome_arquivo', 'Edição na plataforma'),
            'antes', to_jsonb(anterior), 'depois', linha)::text);
      END IF;
      UPDATE public.orcamento_itens SET meta_id = (linha->>'meta_id')::uuid,
        grupo = linha->>'grupo', categoria = linha->>'categoria', item = linha->>'item',
        qtd = (linha->>'qtd')::numeric, unidade = linha->>'unidade', qtd_unidades = (linha->>'qtd_unidades')::numeric,
        valor_unitario = (linha->>'valor_unitario')::numeric, valor_proposto = (linha->>'valor_proposto')::numeric,
        chave_origem = linha->>'chave_origem', ordem = posicao, importacao_id = coalesce(v_importacao_id, orcamento_itens.importacao_id)
        WHERE id = item_id;
    ELSE
      INSERT INTO public.orcamento_itens(projeto_id, meta_id, grupo, categoria, item, qtd, unidade,
        qtd_unidades, valor_unitario, valor_proposto, chave_origem, ordem, importacao_id, situacao, valor_executado)
      VALUES(p_projeto, (linha->>'meta_id')::uuid, linha->>'grupo', linha->>'categoria', linha->>'item',
        (linha->>'qtd')::numeric, linha->>'unidade', (linha->>'qtd_unidades')::numeric,
        (linha->>'valor_unitario')::numeric, (linha->>'valor_proposto')::numeric,
        linha->>'chave_origem', posicao, v_importacao_id, 'Ativo', NULL) RETURNING id INTO item_id;
      incluidos := incluidos + 1;
      INSERT INTO public.orcamento_item_historico(item_id, evento, autor, valor_novo, detalhe)
        VALUES(item_id, 'importação', p_autor, linha->>'valor_proposto',
          coalesce(p_importacao->>'nome_arquivo', 'Inclusão na plataforma'));
    END IF;
    ids := array_append(ids, item_id);
  END LOOP;
  FOR anterior IN SELECT * FROM public.orcamento_itens WHERE projeto_id = p_projeto AND vigente AND NOT (id = ANY(ids)) LOOP
    UPDATE public.orcamento_itens SET vigente = false WHERE id = anterior.id;
    arquivados := arquivados + 1;
    INSERT INTO public.orcamento_item_historico(item_id, evento, autor, valor_anterior, valor_novo, detalhe)
      VALUES(anterior.id, 'correção de origem', p_autor, anterior.valor_proposto::text, NULL,
        'Item substituído na nova versão do orçamento. Notas e execução preservadas.');
  END LOOP;
  IF v_importacao_id IS NOT NULL THEN
    UPDATE public.orcamento_importacoes SET resumo = coalesce(resumo, '{}'::jsonb) ||
      jsonb_build_object('incluidos', incluidos, 'alterados', alterados, 'ausentes', arquivados, 'metasCriadas', metas_criadas)
      WHERE id = v_importacao_id;
  END IF;
  RETURN jsonb_build_object('incluidos', incluidos, 'alterados', alterados, 'ausentes', arquivados, 'versao', versao);
END $$

-- Uma referência compartilhada; cada importação/correção cria snapshot imutável.
CREATE TABLE public.cronograma_rotas (
  id text PRIMARY KEY CHECK (id = 'principal'),
  versao bigint NOT NULL CHECK (versao > 0),
  dados jsonb NOT NULL CHECK (jsonb_typeof(dados) = 'object'),
  autor text NOT NULL,
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.cronograma_rotas_historico (
  versao bigint PRIMARY KEY,
  dados jsonb NOT NULL,
  autor text NOT NULL,
  motivo text NOT NULL,
  criado_em timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.cronograma_rotas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cronograma_rotas_historico ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cronograma_rotas, public.cronograma_rotas_historico FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.cronograma_rotas TO service_role;
GRANT SELECT, INSERT ON public.cronograma_rotas_historico TO service_role;

CREATE FUNCTION public.salvar_cronograma_rotas(p_versao bigint, p_dados jsonb, p_autor text, p_motivo text)
RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp AS $$
DECLARE atual bigint; nova bigint;
BEGIN
  IF p_versao IS NULL OR p_versao < 0 OR p_dados IS NULL OR
     jsonb_typeof(p_dados) IS DISTINCT FROM 'object' OR
     p_dados->>'schema' IS DISTINCT FROM '1' OR
     jsonb_typeof(p_dados->'abas') IS DISTINCT FROM 'array' OR
     octet_length(p_dados::text) > 3000000 OR
     nullif(trim(p_autor),'') IS NULL OR nullif(trim(p_motivo),'') IS NULL THEN
    RAISE EXCEPTION 'Dados do cronograma inválidos.';
  END IF;
  -- Serializa inclusive a primeira importação, quando a linha ainda não existe.
  PERFORM pg_advisory_xact_lock(hashtext('inova:cronograma_rotas:principal'));
  SELECT versao INTO atual FROM public.cronograma_rotas WHERE id='principal' FOR UPDATE;
  IF coalesce(atual,0) <> p_versao THEN
    RAISE EXCEPTION 'O cronograma foi alterado por outra pessoa. Recarregue antes de salvar.';
  END IF;
  nova := p_versao + 1;
  INSERT INTO public.cronograma_rotas(id,versao,dados,autor) VALUES('principal',nova,p_dados,p_autor)
    ON CONFLICT(id) DO UPDATE SET versao=EXCLUDED.versao,dados=EXCLUDED.dados,autor=EXCLUDED.autor,atualizado_em=clock_timestamp();
  INSERT INTO public.cronograma_rotas_historico(versao,dados,autor,motivo) VALUES(nova,p_dados,p_autor,p_motivo);
  RETURN nova;
END $$;
REVOKE ALL ON FUNCTION public.salvar_cronograma_rotas(bigint,jsonb,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.salvar_cronograma_rotas(bigint,jsonb,text,text) TO service_role;
